package com.acme.relay.config;

import java.io.IOException;
import java.io.Reader;
import java.net.URI;
import java.net.URISyntaxException;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the relay's configuration from a properties file.
 *
 * <p>Any problem with the file (unreadable, unknown key, value that does not parse or is out of range) is a
 * {@link ConfigException} listing every problem found, so the service never starts on values nobody chose.
 */
public final class ConfigLoader {
    static final int DEFAULT_WORKER_THREADS = 4;
    static final int DEFAULT_QUEUE_CAPACITY = 1000;
    static final int DEFAULT_RETRY_ATTEMPTS = 3;
    static final Duration DEFAULT_REQUEST_TIMEOUT = Duration.ofSeconds(30);
    static final boolean DEFAULT_METRICS_ENABLED = false;

    static final String UPSTREAM_URL = "upstream.url";
    static final String API_TOKEN = "api.token";
    static final String WORKER_THREADS = "worker.threads";
    static final String QUEUE_CAPACITY = "queue.capacity";
    static final String RETRY_MAX_ATTEMPTS = "retry.max-attempts";
    static final String REQUEST_TIMEOUT = "request.timeout";
    static final String METRICS_ENABLED = "metrics.enabled";

    private static final Set<String> KNOWN_KEYS = Set.of(
            UPSTREAM_URL, API_TOKEN, WORKER_THREADS, QUEUE_CAPACITY, RETRY_MAX_ATTEMPTS, REQUEST_TIMEOUT,
            METRICS_ENABLED);

    private static final Pattern DURATION = Pattern.compile("(\\d+)(ms|s|m)");

    private ConfigLoader() {}

    public static ServiceConfig load(Path file) {
        Settings settings = new Settings(read(file));
        settings.rejectUnknownKeys();
        ServiceConfig config = new ServiceConfig(
                settings.requiredUrl(UPSTREAM_URL),
                settings.requiredText(API_TOKEN),
                settings.intAtLeast(WORKER_THREADS, DEFAULT_WORKER_THREADS, 1),
                settings.intAtLeast(QUEUE_CAPACITY, DEFAULT_QUEUE_CAPACITY, 1),
                settings.intAtLeast(RETRY_MAX_ATTEMPTS, DEFAULT_RETRY_ATTEMPTS, 0),
                settings.duration(REQUEST_TIMEOUT, DEFAULT_REQUEST_TIMEOUT),
                settings.bool(METRICS_ENABLED, DEFAULT_METRICS_ENABLED));
        if (!settings.problems.isEmpty()) {
            throw new ConfigException(
                    "Invalid configuration in " + file + ":\n  - " + String.join("\n  - ", settings.problems));
        }
        return config;
    }

    private static Properties read(Path file) {
        Properties properties = new Properties();
        try (Reader reader = Files.newBufferedReader(file)) {
            properties.load(reader);
        } catch (NoSuchFileException e) {
            throw new ConfigException("Configuration file not found: " + file.toAbsolutePath(), e);
        } catch (IOException | IllegalArgumentException e) {
            throw new ConfigException("Cannot read configuration file " + file.toAbsolutePath() + ": " + e, e);
        }
        return properties;
    }

    /** Parses individual keys, collecting a problem instead of a value for anything unusable. */
    private static final class Settings {
        private final Properties properties;
        private final List<String> problems = new ArrayList<>();

        Settings(Properties properties) {
            this.properties = properties;
        }

        void rejectUnknownKeys() {
            Set<String> unknown = new TreeSet<>(properties.stringPropertyNames());
            unknown.removeAll(KNOWN_KEYS);
            for (String key : unknown) {
                problems.add(key + ": unknown key (expected one of " + new TreeSet<>(KNOWN_KEYS) + ")");
            }
        }

        URI requiredUrl(String key) {
            String raw = requiredText(key);
            if (raw == null) {
                return null;
            }
            try {
                URI uri = new URI(raw);
                if (("http".equals(uri.getScheme()) || "https".equals(uri.getScheme())) && uri.getHost() != null) {
                    return uri;
                }
            } catch (URISyntaxException e) {
                // reported below like any other unusable URL
            }
            invalid(key, raw, "an absolute http or https URL");
            return null;
        }

        /** The trimmed value; reports the key without echoing its value, since it may be a secret. */
        String requiredText(String key) {
            String raw = properties.getProperty(key);
            if (raw == null || raw.isBlank()) {
                problems.add(key + ": required but not set");
                return null;
            }
            return raw.trim();
        }

        int intAtLeast(String key, int defaultValue, int minimum) {
            String raw = optional(key);
            if (raw == null) {
                return defaultValue;
            }
            String expected = "a whole number of at least " + minimum;
            try {
                int value = Integer.parseInt(raw);
                if (value >= minimum) {
                    return value;
                }
            } catch (NumberFormatException e) {
                // reported below
            }
            invalid(key, raw, expected);
            return defaultValue;
        }

        Duration duration(String key, Duration defaultValue) {
            String raw = optional(key);
            if (raw == null) {
                return defaultValue;
            }
            Matcher matcher = DURATION.matcher(raw);
            if (matcher.matches()) {
                try {
                    long amount = Long.parseLong(matcher.group(1));
                    Duration value = switch (matcher.group(2)) {
                        case "ms" -> Duration.ofMillis(amount);
                        case "s" -> Duration.ofSeconds(amount);
                        default -> Duration.ofMinutes(amount);
                    };
                    value.toMillis(); // the uplink works in milliseconds; reject what it cannot represent
                    return value;
                } catch (ArithmeticException | NumberFormatException e) {
                    // too large; reported below
                }
            }
            invalid(key, raw, "a whole number followed by ms, s or m, for example 30s");
            return defaultValue;
        }

        boolean bool(String key, boolean defaultValue) {
            String raw = optional(key);
            if (raw == null) {
                return defaultValue;
            }
            if (raw.equals("true") || raw.equals("false")) {
                return Boolean.parseBoolean(raw);
            }
            invalid(key, raw, "true or false");
            return defaultValue;
        }

        /** The trimmed value, or null when the key is absent. A key that is present but blank is a problem. */
        private String optional(String key) {
            String raw = properties.getProperty(key);
            if (raw == null) {
                return null;
            }
            return raw.trim();
        }

        private void invalid(String key, String raw, String expected) {
            problems.add(key + ": '" + raw + "' is not valid, expected " + expected);
        }
    }
}

