@Test
void apiTokenIsNotEchoedWhenBlank() throws IOException {
    String message = rejectionOf("upstream.url=https://uplink.example.com/v1/events\napi.token=   \n");

    assertTrue(message.contains("api.token: required but not set"), message);
}

@Test
void upstreamUrlIsRequired() throws IOException {
    assertTrue(rejectionOf("api.token=s3cret\n").contains("upstream.url: required but not set"));
}

@Test
void rejectsAnUpstreamUrlThatIsNotAnHttpUrl() throws IOException {
    for (String url : List.of("uplink.example.com/v1", "ftp://uplink.example.com/", "https://exa mple.com/")) {
        String message = rejectionOf("api.token=s3cret\nupstream.url=" + url + "\n");

        assertTrue(message.contains("upstream.url: '" + url + "' is not valid"), message);
    }
}

@Test
void rejectsAWorkerCountWithALetterInIt() throws IOException {
    String message = rejectionOf(REQUIRED + "worker.threads=1O\n");

    assertTrue(message.contains("worker.threads: '1O' is not valid, expected a whole number of at least 1"), message);
}

@Test
void acceptsEachNumberAtItsMinimum() throws IOException {
    ServiceConfig config = ConfigLoader.load(
            write(REQUIRED + "worker.threads=1\nqueue.capacity=1\nretry.max-attempts=0\n"));

    assertEquals(1, config.workerThreads());
    assertEquals(1, config.queueCapacity());
    assertEquals(0, config.retryAttempts());
}

@Test
void rejectsEachNumberBelowItsMinimum() throws IOException {
    assertTrue(rejectionOf(REQUIRED + "worker.threads=0\n").contains("worker.threads: '0'"));
    assertTrue(rejectionOf(REQUIRED + "queue.capacity=0\n").contains("queue.capacity: '0'"));
    assertTrue(rejectionOf(REQUIRED + "retry.max-attempts=-1\n").contains("retry.max-attempts: '-1'"));
}

@Test
void rejectsANumberTooLargeForAnInt() throws IOException {
    assertTrue(rejectionOf(REQUIRED + "queue.capacity=3000000000\n").contains("queue.capacity: '3000000000'"));
}

@Test
void rejectsAKeyThatIsPresentButEmpty() throws IOException {
    assertTrue(rejectionOf(REQUIRED + "worker.threads=\n").contains("worker.threads: '' is not valid"));
}

@Test
void rejectsATimeoutWithoutAUnit() throws IOException {
    String message = rejectionOf(REQUIRED + "request.timeout=30\n");

    assertTrue(message.contains("request.timeout: '30' is not valid, expected a whole number followed by"), message);
}

@Test
void rejectsATimeoutTooLargeToRepresent() throws IOException {
    assertTrue(rejectionOf(REQUIRED + "request.timeout=99999999999999999999m\n").contains("request.timeout"));
    assertTrue(rejectionOf(REQUIRED + "request.timeout=9223372036854775807s\n").contains("request.timeout"));
}

@Test
void rejectsAMetricsFlagThatIsNotTrueOrFalse() throws IOException {
    String message = rejectionOf(REQUIRED + "metrics.enabled=ture\n");

    assertTrue(message.contains("metrics.enabled: 'ture' is not valid, expected true or false"), message);
}

@Test
void rejectsAMisspelledKey() throws IOException {
    String message = rejectionOf(REQUIRED + "worker.thread=8\n");

    assertTrue(message.contains("worker.thread: unknown key"), message);
}

@Test
void reportsEveryProblemAtOnce() throws IOException {
    String message = rejectionOf("worker.threads=four\nmetrics.enabled=yes\n");

    assertTrue(message.startsWith("Invalid configuration in " + dir.resolve("config.properties")), message);
    assertTrue(message.contains("upstream.url"), message);
    assertTrue(message.contains("api.token"), message);
    assertTrue(message.contains("worker.threads"), message);
    assertTrue(message.contains("metrics.enabled"), message);
}

@Test
void rejectsAMissingFile() {
    Path missing = dir.resolve("nope.properties");

    ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(missing));

    assertTrue(error.getMessage().contains("not found"), error.getMessage());
    assertTrue(error.getMessage().contains("nope.properties"), error.getMessage());
}

private String rejectionOf(String content) throws IOException {
    Path file = write(content);
    return assertThrows(ConfigException.class, () -> ConfigLoader.load(file)).getMessage();
}

private Path write(String content) throws IOException {
    return Files.writeString(dir.resolve("config.properties"), content);
}

