        for (String url : List.of("uplink.example.com/v1", "ftp://uplink.example.com/", "https://exa mple.com/")) {
            String message = rejectionOf("api.token=s3cret\nupstream.url=" + url + "\n");

            assertTrue(message.contains("upstream.url: '" + url + "' is not valid"), message);
        }
